PREPARE p9_vector_query (VECTOR(64), STRING, STRING, INT8) AS
SELECT vector_id, encode(event_hash,'hex') AS event_hash,
       encode(vector_digest,'hex') AS vector_digest,
       vector <-> $1 AS distance
FROM ck.context_vectors
WHERE task_id = $2 AND namespace = $3
ORDER BY vector <-> $1
LIMIT $4;
EXECUTE p9_vector_query('[0.000000,0.000000,0.000000,0.000000,0.000000,0.277759,0.000000,0.000000,0.000000,0.000000,-0.382172,0.276745,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.460229,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.336555,0.000000,-0.349733,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.502805,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000]'::VECTOR(64),'ck-p9-live-promote-r1','ck-p9-completion',8);
DEALLOCATE p9_vector_query;
